/**
 * The project map: projection of the base map frames generated by
 * scripts/build-map.mjs, and the grouping of project places into markers.
 * Places that share an `area` share a marker; a marker is only as precise as
 * its least precise place.
 */
import data from './map-data.json';
import type { Project } from '../content';

export type FrameKey = 'south-asia' | 'iberia';

export interface Frame {
  bbox: [number, number, number, number];
  width: number;
  height: number;
  land: string;
  lakes: string;
  rivers: { d: string; rank: number }[];
}

export const FRAMES = data.frames as unknown as Record<FrameKey, Frame>;
export const MAP_SOURCE = data.source;

export function project(frame: Frame, lon: number, lat: number): [number, number] {
  const [lon0, lat0, lon1, lat1] = frame.bbox;
  const phi = (((lat0 + lat1) / 2) * Math.PI) / 180;
  const s = frame.width / ((lon1 - lon0) * Math.cos(phi));
  return [(lon - lon0) * s * Math.cos(phi), (lat1 - lat) * s];
}

/** Units per degree of latitude, for the scale bar. */
export function unitsPerDegree(frame: Frame): number {
  const [lon0, lat0, lon1, lat1] = frame.bbox;
  const phi = (((lat0 + lat1) / 2) * Math.PI) / 180;
  return frame.width / ((lon1 - lon0) * Math.cos(phi));
}

const inside = (f: Frame, lon: number, lat: number) =>
  lon >= f.bbox[0] && lon <= f.bbox[2] && lat >= f.bbox[1] && lat <= f.bbox[3];

const RANK = ['site', 'locality', 'city', 'district', 'region'] as const;

export interface Marker {
  id: string;
  frame: FrameKey;
  label: string;
  lon: number;
  lat: number;
  precision: (typeof RANK)[number];
  places: { name: string; precision: string; note?: string; project: Project }[];
  projects: Project[];
}

export function markers(projects: Project[]): Marker[] {
  const groups = new Map<string, Marker>();
  for (const p of projects) {
    for (const place of p.data.places) {
      const frame = (Object.keys(FRAMES) as FrameKey[]).find((k) => inside(FRAMES[k], place.lon, place.lat));
      if (!frame) throw new Error(`projects/${p.id}: ${place.name} lies outside the project map`);
      const key = place.area ?? place.name;
      const id = `place-${key
        .toLowerCase()
        .normalize('NFKD')
        .replace(/[̀-ͯ]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '')}`;
      const m = groups.get(key) ?? {
        id,
        frame,
        label: key,
        lon: 0,
        lat: 0,
        precision: 'site' as Marker['precision'],
        places: [],
        projects: [],
      };
      m.places.push({ name: place.name, precision: place.precision, note: place.note, project: p });
      if (!m.projects.includes(p)) m.projects.push(p);
      if (RANK.indexOf(place.precision) > RANK.indexOf(m.precision)) m.precision = place.precision;
      groups.set(key, m);
    }
  }
  for (const m of groups.values()) {
    m.lon = m.places.reduce((s, x) => s + x.project.data.places.find((pl) => pl.name === x.name)!.lon, 0) / m.places.length;
    m.lat = m.places.reduce((s, x) => s + x.project.data.places.find((pl) => pl.name === x.name)!.lat, 0) / m.places.length;
  }
  return [...groups.values()].sort((a, b) => b.projects.length - a.projects.length || a.label.localeCompare(b.label));
}
